ON CONFLICT (id) DO UPDATE SET
  empresa = EXCLUDED.empresa, mes_fechamento = EXCLUDED.mes_fechamento,
  classificacao = EXCLUDED.classificacao, titulo = EXCLUDED.titulo,
  resumo = EXCLUDED.resumo, abertura = EXCLUDED.abertura,
  ultimo_retorno = EXCLUDED.ultimo_retorno, sla_horas_corridas = EXCLUDED.sla_horas_corridas,
  sla_horas_uteis = EXCLUDED.sla_horas_uteis, status = EXCLUDED.status,
  link = EXCLUDED.link, synced_at = NOW();
